  1354  /**
  1355   * xmlParserNsLookup:
  1356   * @ctxt: parser context
  1357   * @prefix: namespace prefix
  1358   * @bucketPtr: optional bucket (return value)
  1359   *
  1360   * Lookup namespace with given prefix. If @bucketPtr is non-NULL, it will
  1361   * be set to the matching bucket, or the first empty bucket if no match
  1362   * was found.
  1363   *
  1364   * Returns the namespace index on success, INT_MAX if no namespace was
  1365   * found.
  1366   */
  1367  static int
  1368  xmlParserNsLookup(xmlParserCtxtPtr ctxt, const xmlHashedString *prefix,
  1369                    xmlParserNsBucket **bucketPtr) {
  1370      xmlParserNsBucket *bucket;
  1371      unsigned index, hashValue;
  1372
  1373      if (prefix->name == NULL)
  1374          return(ctxt->nsdb->defaultNsIndex);
  1375
  1376      if (ctxt->nsdb->hashSize == 0)
  1377          return(INT_MAX);
  1378
  1379      hashValue = prefix->hashValue;
  1380      index = hashValue & (ctxt->nsdb->hashSize - 1);
  1381      bucket = &ctxt->nsdb->hash[index];
  1382
  1383      while (bucket->hashValue) {
  1384          if ((bucket->hashValue == hashValue) &&
  1385              (bucket->index != INT_MAX)) {
  1386              if (ctxt->nsTab[bucket->index * 2] == prefix->name) {
  1387                  if (bucketPtr != NULL)
  1388                      *bucketPtr = bucket;
  1389                  return(bucket->index);
  1390              }
  1391          }
  1392
  1393          index++;
  1394          bucket++;
  1395          if (index == ctxt->nsdb->hashSize) {
  1396              index = 0;
  1397              bucket = ctxt->nsdb->hash;
  1398          }
  1399      }
  1400
  1401      if (bucketPtr != NULL)
  1402          *bucketPtr = bucket;
  1403      return(INT_MAX);
  1404  }
