  1415  static const xmlChar *
  1416  xmlParserNsLookupUri(xmlParserCtxtPtr ctxt, const xmlHashedString *prefix) {
  1417      const xmlChar *ret;
  1418      int nsIndex;
  1419
  1420      if (prefix->name == ctxt->str_xml)
  1421          return(ctxt->str_xml_ns);
  1422
  1423      nsIndex = xmlParserNsLookup(ctxt, prefix, NULL);
  1424      if (nsIndex == INT_MAX)
