  1497  /**
  1498   * xmlParserNsGrow:
  1499   * @ctxt: parser context
  1500   *
  1501   * Grows the namespace tables.
  1502   *
  1503   * Returns 0 on success, -1 if a memory allocation failed.
  1504   */
  1505  static int
  1506  xmlParserNsGrow(xmlParserCtxtPtr ctxt) {
  1507      const xmlChar **table;
  1508      xmlParserNsExtra *extra;
  1509      int newSize;
  1510
  1511      if (ctxt->nsMax > INT_MAX / 2)
  1512          goto error;
  1513      newSize = ctxt->nsMax ? ctxt->nsMax * 2 : 16;
  1514
  1515      table = xmlRealloc(ctxt->nsTab, 2 * newSize * sizeof(table[0]));
  1516      if (table == NULL)
  1517          goto error;
  1518      ctxt->nsTab = table;
  1519
  1520      extra = xmlRealloc(ctxt->nsdb->extra, newSize * sizeof(extra[0]));
  1521      if (extra == NULL)
  1522          goto error;
  1523      ctxt->nsdb->extra = extra;
  1524
  1525      ctxt->nsMax = newSize;
  1526      return(0);
  1527
  1528  error:
  1529      xmlErrMemory(ctxt);
  1530      return(-1);
  1531  }
