  1533  /**
  1534   * xmlParserNsPush:
  1535   * @ctxt: parser context
  1536   * @prefix: prefix with hash value
  1537   * @uri: uri with hash value
  1538   * @saxData: extra data for SAX handler
  1539   * @defAttr: whether the namespace comes from a default attribute
  1540   *
  1541   * Push a new namespace on the table.
  1542   *
  1543   * Returns 1 if the namespace was pushed, 0 if the namespace was ignored,
  1544   * -1 if a memory allocation failed.
  1545   */
  1546  static int
  1547  xmlParserNsPush(xmlParserCtxtPtr ctxt, const xmlHashedString *prefix,
  1548                  const xmlHashedString *uri, void *saxData, int defAttr) {
  1549      xmlParserNsBucket *bucket = NULL;
  1550      xmlParserNsExtra *extra;
  1551      const xmlChar **ns;
  1552      unsigned hashValue, nsIndex, oldIndex;
  1553
  1554      if ((prefix != NULL) && (prefix->name == ctxt->str_xml))
  1555          return(0);
  1556
  1557      if ((ctxt->nsNr >= ctxt->nsMax) && (xmlParserNsGrow(ctxt) < 0)) {
  1558          xmlErrMemory(ctxt);
  1559          return(-1);
  1560      }
  1561
  1562      /*
  1563       * Default namespace and 'xml' namespace
  1564       */
  1565      if ((prefix == NULL) || (prefix->name == NULL)) {
  1566          oldIndex = ctxt->nsdb->defaultNsIndex;
  1567
  1568          if (oldIndex != INT_MAX) {
  1569              extra = &ctxt->nsdb->extra[oldIndex];
  1570
  1571              if (extra->elementId == ctxt->nsdb->elementId) {
  1572                  if (defAttr == 0)
  1573                      xmlErrAttributeDup(ctxt, NULL, BAD_CAST "xmlns");
  1574                  return(0);
  1575              }
  1576
  1577              if ((ctxt->options & XML_PARSE_NSCLEAN) &&
  1578                  (uri->name == ctxt->nsTab[oldIndex * 2 + 1]))
  1579                  return(0);
  1580          }
  1581
  1582          ctxt->nsdb->defaultNsIndex = ctxt->nsNr;
  1583          goto populate_entry;
  1584      }
  1585
  1586      /*
  1587       * Hash table lookup
  1588       */
  1589      oldIndex = xmlParserNsLookup(ctxt, prefix, &bucket);
  1590      if (oldIndex != INT_MAX) {
  1591          extra = &ctxt->nsdb->extra[oldIndex];
  1592
  1593          /*
  1594           * Check for duplicate definitions on the same element.
  1595           */
  1596          if (extra->elementId == ctxt->nsdb->elementId) {
  1597              if (defAttr == 0)
  1598                  xmlErrAttributeDup(ctxt, BAD_CAST "xmlns", prefix->name);
  1599              return(0);
  1600          }
  1601
  1602          if ((ctxt->options & XML_PARSE_NSCLEAN) &&
  1603              (uri->name == ctxt->nsTab[bucket->index * 2 + 1]))
  1604              return(0);
  1605
  1606          bucket->index = ctxt->nsNr;
  1607          goto populate_entry;
  1608      }
  1609
  1610      /*
  1611       * Insert new bucket
  1612       */
  1613
  1614      hashValue = prefix->hashValue;
  1615
  1616      /*
  1617       * Grow hash table, 50% fill factor
  1618       */
  1619      if (ctxt->nsdb->hashElems + 1 > ctxt->nsdb->hashSize / 2) {
  1620          xmlParserNsBucket *newHash;
  1621          unsigned newSize, i, index;
  1622
  1623          if (ctxt->nsdb->hashSize > UINT_MAX / 2) {
  1624              xmlErrMemory(ctxt);
  1625              return(-1);
  1626          }
  1627          newSize = ctxt->nsdb->hashSize ? ctxt->nsdb->hashSize * 2 : 16;
  1628          newHash = xmlMalloc(newSize * sizeof(newHash[0]));
  1629          if (newHash == NULL) {
  1630              xmlErrMemory(ctxt);
  1631              return(-1);
  1632          }
  1633          memset(newHash, 0, newSize * sizeof(newHash[0]));
  1634
  1635          for (i = 0; i < ctxt->nsdb->hashSize; i++) {
  1636              unsigned hv = ctxt->nsdb->hash[i].hashValue;
  1637              unsigned newIndex;
  1638
  1639              if (hv == 0)
  1640                  continue;
  1641              newIndex = hv & (newSize - 1);
  1642
  1643              while (newHash[newIndex].hashValue != 0) {
  1644                  newIndex++;
  1645                  if (newIndex == newSize)
  1646                      newIndex = 0;
  1647              }
  1648
  1649              newHash[newIndex] = ctxt->nsdb->hash[i];
  1650          }
  1651
  1652          xmlFree(ctxt->nsdb->hash);
  1653          ctxt->nsdb->hash = newHash;
  1654          ctxt->nsdb->hashSize = newSize;
  1655
  1656          /*
  1657           * Relookup
  1658           */
  1659          index = hashValue & (newSize - 1);
  1660
  1661          while (newHash[index].hashValue != 0) {
  1662              index++;
  1663              if (index == newSize)
  1664                  index = 0;
  1665          }
  1666
  1667          bucket = &newHash[index];
  1668      }
  1669
  1670      bucket->hashValue = hashValue;
  1671      bucket->index = ctxt->nsNr;
  1672      ctxt->nsdb->hashElems++;
  1673      oldIndex = INT_MAX;
  1674
  1675  populate_entry:
  1676      nsIndex = ctxt->nsNr;
  1677
  1678      ns = &ctxt->nsTab[nsIndex * 2];
  1679      ns[0] = prefix ? prefix->name : NULL;
  1680      ns[1] = uri->name;
  1681
  1682      extra = &ctxt->nsdb->extra[nsIndex];
  1683      extra->saxData = saxData;
  1684      extra->prefixHashValue = prefix ? prefix->hashValue : 0;
  1685      extra->uriHashValue = uri->hashValue;
  1686      extra->elementId = ctxt->nsdb->elementId;
  1687      extra->oldIndex = oldIndex;
  1688
  1689      ctxt->nsNr++;
  1690
  1691      return(1);
  1692  }
