  1694  /**
  1695   * xmlParserNsPop:
  1696   * @ctxt: an XML parser context
  1697   * @nr:  the number to pop
  1698   *
  1699   * Pops the top @nr namespaces and restores the hash table.
  1700   *
  1701   * Returns the number of namespaces popped.
  1702   */
  1703  static int
  1704  xmlParserNsPop(xmlParserCtxtPtr ctxt, int nr)
  1705  {
  1706      int i;
  1707
  1708      /* assert(nr <= ctxt->nsNr); */
  1709
  1710      for (i = ctxt->nsNr - 1; i >= ctxt->nsNr - nr; i--) {
  1711          const xmlChar *prefix = ctxt->nsTab[i * 2];
  1712          xmlParserNsExtra *extra = &ctxt->nsdb->extra[i];
  1713
  1714          if (prefix == NULL) {
  1715              ctxt->nsdb->defaultNsIndex = extra->oldIndex;
  1716          } else {
  1717              xmlHashedString hprefix;
  1718              xmlParserNsBucket *bucket = NULL;
  1719
  1720              hprefix.name = prefix;
  1721              hprefix.hashValue = extra->prefixHashValue;
  1722              xmlParserNsLookup(ctxt, &hprefix, &bucket);
  1723              /* assert(bucket && bucket->hashValue); */
  1724              bucket->index = extra->oldIndex;
  1725          }
  1726      }
  1727
  1728      ctxt->nsNr -= nr;
  1729      return(nr);
  1730  }
